#!/usr/bin/env bash
# Copies the canonical shared Go helpers (shared/go/common) into each
# service's internal/common package. Every service is its own Go module with
# its own Docker build context, so the code is vendored as generated files.
#
#   scripts/sync-go-common.sh          # write the copies
#   scripts/sync-go-common.sh --check  # fail if a copy is stale (CI)
#
# To adopt a helper in another service, add "<service>:<file>" to MANIFEST.
set -euo pipefail

ROOT="$(cd "$(dirname "$0")/.." && pwd)"
SRC="$ROOT/shared/go/common"
MANIFEST=(
  "core:correlation.go"
  "notification:correlation.go"
  "notification:exception_report.go"
)

check=0
[[ "${1:-}" == "--check" ]] && check=1

render() {
  printf '// Code generated by scripts/sync-go-common.sh from shared/go/common/%s. DO NOT EDIT.\n\n' "$1"
  cat "$SRC/$1"
}

stale=0
for entry in "${MANIFEST[@]}"; do
  svc="${entry%%:*}"
  file="${entry#*:}"
  for f in "$file" "${file%.go}_test.go"; do
    [[ -f "$SRC/$f" ]] || continue
    dst="$ROOT/services/$svc/internal/common/$f"
    if (( check )); then
      if ! diff -q <(render "$f") "$dst" >/dev/null 2>&1; then
        echo "stale: services/$svc/internal/common/$f" >&2
        stale=1
      fi
    else
      mkdir -p "$(dirname "$dst")"
      render "$f" > "$dst"
      echo "synced services/$svc/internal/common/$f"
    fi
  done
done

if (( stale )); then
  echo "run scripts/sync-go-common.sh to refresh the copies" >&2
  exit 1
fi
